import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const STATUS_EVENTS = {
  SessionStart: undefined,
  UserPromptSubmit: undefined,
  PreToolUse: 'AskUserQuestion',
  PermissionRequest: undefined,
  PostToolUse: undefined,
  PostToolUseFailure: undefined,
  Stop: undefined,
  SessionEnd: undefined,
};

const scriptCommand = (script) => {
  const file = fileURLToPath(new URL(`./${script}`, import.meta.url)).replaceAll('\\', '/');

  return `node "${file}"`;
};

const hookEntries = () => [
  ...Object.entries(STATUS_EVENTS).map(([event, matcher]) => ({ event, matcher, command: scriptCommand('status-hook.mjs'), async: true })),
  { event: 'SessionStart', command: scriptCommand('turn-status-hook.mjs'), async: false },
];

const hasCommand = (group, command) => (group.hooks ?? []).some((hook) => hook.command === command);

const hookGroup = ({ matcher, command, async }) => {
  const hook = async ? { type: 'command', command, async: true } : { type: 'command', command };

  return matcher ? { matcher, hooks: [hook] } : { hooks: [hook] };
};

const withStatusHooks = (settings, entries) => {
  const hooks = { ...(settings.hooks ?? {}) };

  for (const entry of entries) {
    const groups = hooks[entry.event] ?? [];

    if (!groups.some((group) => hasCommand(group, entry.command)))
      hooks[entry.event] = [...groups, hookGroup(entry)];
  }

  return { ...settings, hooks };
};

const withoutStatusHooks = (settings, commands) => {
  const hooks = {};

  for (const [event, groups] of Object.entries(settings.hooks ?? {})) {
    const kept = groups
      .map((group) => ({ ...group, hooks: (group.hooks ?? []).filter((hook) => !commands.includes(hook.command)) }))
      .filter((group) => group.hooks.length > 0);

    if (kept.length > 0)
      hooks[event] = kept;
  }

  const { hooks: _removed, ...rest } = settings;

  return Object.keys(hooks).length > 0 ? { ...rest, hooks } : rest;
};

const settingsFile = () => join(homedir(), '.claude', 'settings.json');

const run = (uninstall) => {
  const file = settingsFile();
  const settings = existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : {};

  if (existsSync(file)) {
    const backup = `${file}.backup-${new Date().toISOString().replace(/[:.]/g, '-')}`;

    copyFileSync(file, backup);
    console.log(`Backed up ${file} to ${backup}`);
  }

  const entries = hookEntries();
  const commands = [...new Set(entries.map((entry) => entry.command))];
  const updated = uninstall ? withoutStatusHooks(settings, commands) : withStatusHooks(settings, entries);

  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, `${JSON.stringify(updated, null, 2)}\n`);
  console.log(`${uninstall ? 'Removed' : 'Installed'} the session status hooks (${commands.join(', ')}).`);
};

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)
  run(process.argv.includes('--uninstall'));

export { STATUS_EVENTS, hookEntries, scriptCommand, withStatusHooks, withoutStatusHooks };

const INSTRUCTION = 'End every turn with a final line on its own: `STATUS: QUESTION` when you need the developer\'s answer or decision, `STATUS: DONE` otherwise. The developer\'s session view reads it.';

if (!(process.env.CLAUDE_CODE_ENTRYPOINT ?? '').startsWith('sdk'))
  process.stdout.write(`${INSTRUCTION}\n`);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { STATUS_EVENTS, hookEntries, scriptCommand, withStatusHooks, withoutStatusHooks } from '../status/install.mjs';

const installer = fileURLToPath(new URL('../status/install.mjs', import.meta.url));
const statusCommand = 'node "P:/clone/status/status-hook.mjs"';
const turnCommand = 'node "P:/clone/status/turn-status-hook.mjs"';
const entries = [
  ...Object.entries(STATUS_EVENTS).map(([event, matcher]) => ({ event, matcher, command: statusCommand, async: true })),
  { event: 'SessionStart', command: turnCommand, async: false },
];

const existing = {
  env: { DOTNET_gcServer: '0' },
  hooks: {
    Stop: [{ hooks: [{ type: 'command', command: 'powershell.exe -NoProfile -Command "play tada"' }] }],
  },
  enabledPlugins: { 'postman@claude-plugins-official': true },
};

const ownGroups = (settings, event, command) => settings.hooks[event].filter((group) => group.hooks.some((hook) => hook.command === command));

test('install adds one asynchronous status entry per event, keeps existing entries, and is idempotent', () => {
  const installed = withStatusHooks(existing, entries);

  assert.deepEqual(Object.keys(installed.hooks).sort(), Object.keys(STATUS_EVENTS).sort());
  assert.deepEqual(installed.hooks.Stop[0], existing.hooks.Stop[0]);
  assert.equal(installed.env, existing.env);
  assert.equal(installed.enabledPlugins, existing.enabledPlugins);

  for (const [event, matcher] of Object.entries(STATUS_EVENTS)) {
    const own = ownGroups(installed, event, statusCommand);

    assert.equal(own.length, 1, event);
    assert.deepEqual(own[0].hooks, [{ type: 'command', command: statusCommand, async: true }], event);
    assert.equal(own[0].matcher, matcher, event);
  }

  assert.deepEqual(withStatusHooks(installed, entries), installed);
});

test('the status-line hook is one synchronous SessionStart entry without matcher', () => {
  const own = ownGroups(withStatusHooks(existing, entries), 'SessionStart', turnCommand);

  assert.deepEqual(own, [{ hooks: [{ type: 'command', command: turnCommand }] }]);
});

test('an existing install gains the status-line hook on the next run', () => {
  const statusOnly = withStatusHooks(existing, entries.filter((entry) => entry.command === statusCommand));
  const upgraded = withStatusHooks(statusOnly, entries);

  assert.equal(ownGroups(upgraded, 'SessionStart', turnCommand).length, 1);
  assert.equal(ownGroups(upgraded, 'SessionStart', statusCommand).length, 1);
});

test('uninstall removes only the toolkit entries and restores the original settings', () => {
  assert.deepEqual(withoutStatusHooks(withStatusHooks(existing, entries), [statusCommand, turnCommand]), existing);
  assert.deepEqual(withoutStatusHooks(withStatusHooks({}, entries), [statusCommand, turnCommand]), {});
});

test('the hook commands point at the clone scripts with forward slashes', () => {
  for (const script of ['status-hook.mjs', 'turn-status-hook.mjs']) {
    assert.match(scriptCommand(script), new RegExp(`^node ".*/status/${script.replace('.', '\\.')}"$`));
    assert.doesNotMatch(scriptCommand(script), /\\/);
  }

  assert.deepEqual(hookEntries().filter((entry) => !entry.async).map((entry) => entry.event), ['SessionStart']);
});

test('running the installer backs up the settings file before writing', () => {
  const home = mkdtempSync(join(tmpdir(), 'toolkit-install-'));

  try {
    const claudeDir = join(home, '.claude');
    const settingsFile = join(claudeDir, 'settings.json');
    const env = { ...process.env, HOME: home, USERPROFILE: home };

    mkdirSync(claudeDir);
    writeFileSync(settingsFile, JSON.stringify(existing));

    const install = spawnSync(process.execPath, [installer], { env, encoding: 'utf8' });

    assert.equal(install.status, 0, install.stderr);

    const backups = readdirSync(claudeDir).filter((entry) => entry.startsWith('settings.json.backup-'));
    const written = JSON.parse(readFileSync(settingsFile, 'utf8'));

    assert.equal(backups.length, 1);
    assert.deepEqual(JSON.parse(readFileSync(join(claudeDir, backups[0]), 'utf8')), existing);
    assert.deepEqual(written.hooks.SessionStart.map((group) => group.hooks[0].command), [scriptCommand('status-hook.mjs'), scriptCommand('turn-status-hook.mjs')]);

    const uninstall = spawnSync(process.execPath, [installer, '--uninstall'], { env, encoding: 'utf8' });

    assert.equal(uninstall.status, 0, uninstall.stderr);
    assert.deepEqual(JSON.parse(readFileSync(settingsFile, 'utf8')), existing);
  } finally {
    rmSync(home, { recursive: true, force: true });
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
const pluginRoot = join(root, 'plugins', 'toolkit');

const readJson = (...segments) => JSON.parse(readFileSync(join(root, ...segments), 'utf8'));
const readAgent = (name) => readFileSync(join(pluginRoot, 'agents', `${name}.md`), 'utf8');
const frontmatter = (text) => /^---\n([\s\S]*?)\n---\n/.exec(text)[1];

test('marketplace lists the toolkit plugin from inside the repository', () => {
  const marketplace = readJson('.claude-plugin', 'marketplace.json');

  assert.equal(marketplace.name, 'claude-toolkit');
  assert.ok(marketplace.owner?.name);
  assert.deepEqual(
    marketplace.plugins.map(({ name, source }) => ({ name, source })),
    [{ name: 'toolkit', source: './plugins/toolkit' }],
  );
});

test('plugin manifest is named toolkit and declares no version', () => {
  const plugin = readJson('plugins', 'toolkit', '.claude-plugin', 'plugin.json');

  assert.equal(plugin.name, 'toolkit');
  assert.equal(Object.hasOwn(plugin, 'version'), false);
});

test('the plugin ships exactly the coordinator and worker agents and the start-up hook', () => {
  assert.deepEqual(readdirSync(pluginRoot).sort(), ['.claude-plugin', 'agents', 'hooks']);
  assert.deepEqual(readdirSync(join(pluginRoot, 'agents')).sort(), ['coordinator.md', 'worker.md']);
  assert.deepEqual(readdirSync(join(pluginRoot, 'hooks')).sort(), ['hooks.json', 'session-start.mjs']);
});

test('agent definitions are named after their files and carry a description', () => {
  for (const name of ['coordinator', 'worker']) {
    const fields = frontmatter(readAgent(name));

    assert.match(fields, new RegExp(`^name: ${name}$`, 'm'));
    assert.match(fields, /^description: \S/m);
  }
});

test('both agents describe the same board paths', () => {
  for (const name of ['coordinator', 'worker']) {
    const prompt = readAgent(name);

    for (const boardPath of ['team.json', 'requests/', 'sessions/', 'log.md', 'brief.md', 'status.md', '<prefix>-coordinator']) {
      assert.ok(prompt.includes(boardPath), `${name} mentions ${boardPath}`);
    }
  }
});

test('both agents end every turn with the status line the session view reads', () => {
  for (const name of ['coordinator', 'worker'])
    assert.match(readAgent(name), /End every turn with a final line on its own: `STATUS: QUESTION` when you need the developer's answer or decision, `STATUS: DONE` otherwise\./, name);
});

test('the coordinator writes requests in the exact shape the extension accepts', () => {
  assert.match(readAgent('coordinator'), /^- `requests\/<name>\.json`: .*containing exactly `\{ "name": "<name>" \}`/m);
});

test('the extension adds only native, labelled VS Code UI: commands, settings and a tree view, no webview', () => {
  const extension = readJson('vscode', 'package.json');
  const { commands, configuration, views, viewsContainers, keybindings } = extension.contributes;

  assert.deepEqual(Object.keys(extension.contributes).sort(), ['commands', 'configuration', 'keybindings', 'menus', 'views', 'viewsContainers']);
  assert.deepEqual(commands.map((command) => command.title), [
    'Toolkit: Enable coordinator in this folder',
    'Toolkit: Start coordinator',
    'Toolkit: Open Claude here on startup',
    'Toolkit: Stop opening Claude here',
    'Toolkit: Show session tab',
    'Toolkit: Hide session until its next event',
    'Toolkit: Show the session waiting longest',
    'Toolkit: Next waiting session',
  ]);
  assert.deepEqual(viewsContainers, { activitybar: [{ id: 'claudeToolkit', title: 'Claude sessions', icon: 'media/sessions.svg' }] });
  assert.deepEqual(views, { claudeToolkit: [{ id: 'claudeToolkit.sessions', name: 'Claude sessions' }] });
  assert.ok(readFileSync(join(root, 'vscode', 'media', 'sessions.svg'), 'utf8').startsWith('<svg'));
  assert.deepEqual(keybindings, [{ command: 'claudeToolkit.nextWaiting', key: 'ctrl+alt+n', mac: 'cmd+alt+n' }]);
  assert.deepEqual(configuration.properties['claudeToolkit.workerLayout'].enum, ['beside', 'tabs']);
  assert.equal(configuration.properties['claudeToolkit.workerLayout'].default, 'beside');

  for (const [key, setting] of Object.entries(configuration.properties)) {
    assert.match(setting.description, /\S{3}/, key);
    assert.equal(setting.scope, 'machine', `${key} cannot be overridden by a workspace`);
  }
});

test('the start-up hook runs when a session starts or resumes', () => {
  const hooks = readJson('plugins', 'toolkit', 'hooks', 'hooks.json').hooks;

  assert.deepEqual(Object.keys(hooks), ['SessionStart']);
  assert.equal(hooks.SessionStart.length, 1);
  assert.equal(hooks.SessionStart[0].matcher, 'startup|resume');
  assert.equal(hooks.SessionStart[0].hooks[0].command, 'node "${CLAUDE_PLUGIN_ROOT}/hooks/session-start.mjs"');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const hook = fileURLToPath(new URL('../status/turn-status-hook.mjs', import.meta.url));

const run = (entrypoint) => spawnSync(process.execPath, [hook], {
  input: '{"hook_event_name":"SessionStart","source":"startup"}',
  encoding: 'utf8',
  env: { ...process.env, CLAUDE_CODE_ENTRYPOINT: entrypoint },
});

test('interactive sessions receive the exact status-line instruction', () => {
  const result = run('cli');

  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, 'End every turn with a final line on its own: `STATUS: QUESTION` when you need the developer\'s answer or decision, `STATUS: DONE` otherwise. The developer\'s session view reads it.\n');
});

test('headless sessions receive nothing', () => {
  for (const entrypoint of ['sdk-cli', 'sdk-ts', 'sdk-py']) {
    const result = run(entrypoint);

    assert.equal(result.status, 0, result.stderr);
    assert.equal(result.stdout, '', entrypoint);
  }
});

test('the instruction matches the one in the coordinator and worker prompts', () => {
  const instruction = run('cli').stdout.trim();

  for (const agent of ['coordinator', 'worker']) {
    const prompt = readFileSync(fileURLToPath(new URL(`../plugins/toolkit/agents/${agent}.md`, import.meta.url)), 'utf8');

    assert.ok(prompt.includes(instruction), agent);
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { join } from 'node:path';
import core from '../vscode/core.js';

const projectFolder = join('P:', 'repos', 'Rehlko', 'rehlko-portal');
const pluginDir = join('P:', 'clone', 'plugins', 'toolkit');

const validate = (overrides) => core.validateRequest({
  fileName: 'tester.json',
  content: '{"name":"tester"}',
  openTabs: ['coordinator'],
  briefExists: () => true,
  ...overrides,
});

test('session prefix is the folder name made safe for session names', () => {
  assert.equal(core.sessionPrefix(projectFolder), 'rehlko-portal');
  assert.equal(core.sessionPrefix(join('P:', 'repos', 'AND EMILI')), 'and-emili');
  assert.equal(core.sessionPrefix(join('P:', 'repos', '__')), 'project');
});

test('a long folder name is cut to 50 characters, so every worker session name stays within the recorded-name limit', () => {
  const prefix = core.sessionPrefix(join('P:', 'repos', `${'a'.repeat(49)}-${'b'.repeat(30)}`));

  assert.equal(prefix, 'a'.repeat(49));
  assert.equal(core.sessionPrefix(join('P:', 'repos', 'c'.repeat(80))).length, 50);
  assert.match(core.workerSessionName(join('P:', 'repos', 'x'.repeat(200)), 'w'.repeat(40)), /^[a-z0-9][a-z0-9-]{0,99}$/);
});

test('coordinator starts as a new named coordinator session in auto mode', () => {
  const args = core.coordinatorArgs({ projectFolder, pluginDir });

  assert.deepEqual(args.slice(0, -1), [
    '--plugin-dir', pluginDir, '--permission-mode', 'auto',
    '--agent', 'toolkit:coordinator', '--name', 'rehlko-portal-coordinator',
  ]);
  assert.match(args.at(-1), /^Start-up: report the team recap/);
});

test('a new worker gets a fixed opening prompt naming its brief', () => {
  assert.deepEqual(core.newWorkerArgs({ projectFolder, pluginDir, name: 'api-auth' }), [
    '--plugin-dir', pluginDir, '--permission-mode', 'auto',
    '--agent', 'toolkit:worker', '--name', 'rehlko-portal-api-auth',
    'Read .coord/workers/api-auth/brief.md and follow it.',
  ]);
});

const sessionId = '7fa97870-6578-4ed2-b7c9-1dc4c9a2ef09';
const workerTail = ['--plugin-dir', pluginDir, '--permission-mode', 'auto', '--agent', 'toolkit:worker'];

test('an active worker with a session record is resumed by that exact session', () => {
  assert.deepEqual(core.resumeWorkerArgs({ projectFolder, pluginDir, name: 'tester', sessionRecord: `${sessionId}\n` }), ['--resume', sessionId, ...workerTail]);
});

test('an active worker without a usable record is resumed by its session name', () => {
  for (const sessionRecord of [undefined, '', 'not-an-id', `${sessionId} --dangerously-skip-permissions`]) {
    assert.deepEqual(core.resumeWorkerArgs({ projectFolder, pluginDir, name: 'tester', sessionRecord }), ['--resume', 'rehlko-portal-tester', ...workerTail], String(sessionRecord));
  }
});

test('a requested worker with a session record continues that session with a fixed prompt', () => {
  assert.deepEqual(core.requestedWorkerArgs({ projectFolder, pluginDir, name: 'tester', sessionRecord: sessionId }), [
    '--resume', sessionId, ...workerTail, 'Read the newest section of .coord/workers/tester/brief.md and follow it.',
  ]);
});

test('a requested worker without a session record starts a new named session', () => {
  assert.deepEqual(core.requestedWorkerArgs({ projectFolder, pluginDir, name: 'tester', sessionRecord: undefined }),
    core.newWorkerArgs({ projectFolder, pluginDir, name: 'tester' }));
});

test('the worker session name joins the project prefix and the worker name', () => {
  assert.equal(core.workerSessionName(projectFolder, 'api-auth'), 'rehlko-portal-api-auth');
});

test('session arguments refuse an invalid worker name', () => {
  for (const name of ['../x', 'a b', 'Tester', 'coordinator', 'claude', '', 'x'.repeat(41)]) {
    assert.throws(() => core.newWorkerArgs({ projectFolder, pluginDir, name }), /Invalid worker name/, name);
    assert.throws(() => core.resumeWorkerArgs({ projectFolder, pluginDir, name }), /Invalid worker name/, name);
    assert.throws(() => core.resumeWorkerArgs({ projectFolder, pluginDir, name, sessionRecord: sessionId }), /Invalid worker name/, name);
    assert.throws(() => core.requestedWorkerArgs({ projectFolder, pluginDir, name, sessionRecord: sessionId }), /Invalid worker name/, name);
    assert.throws(() => core.workerSessionName(projectFolder, name), /Invalid worker name/, name);
  }
});

test('worker names follow the pattern and leave out the coordinator tab', () => {
  for (const name of ['tester', 'api-auth', '9lives', 'a'.repeat(40)]) {
    assert.equal(core.isWorkerName(name), true, name);
  }

  for (const name of ['-x', 'a_b', 'a.b', 'a/b', 'a\\b', 'a"b', 'a;b', 'a$b', 'a b', 'A', 'coordinator', 'claude', 'a'.repeat(41), 42]) {
    assert.equal(core.isWorkerName(name), false, String(name));
  }
});

test('only active workers with valid names are reopened', () => {
  const team = JSON.stringify([
    { name: 'tester', role: 'Tests', state: 'active' },
    { name: 'docs', role: 'Docs', state: 'done' },
    { name: '../evil', role: 'x', state: 'active' },
    { name: 'api', role: 'API', state: 'active' },
  ]);

  assert.deepEqual(core.activeWorkers(team), ['tester', 'api']);
});

test('a team list that is not a JSON array is an error', () => {
  assert.throws(() => core.activeWorkers('{"name":"tester"}'), /JSON array/);
  assert.throws(() => core.activeWorkers('not json'), SyntaxError);
});

test('a valid request opens the named worker', () => {
  assert.deepEqual(validate({}), { ok: true, name: 'tester' });
});

test('hostile or malformed requests are rejected with a reason', () => {
  const cases = [
    [{ fileName: '..json' }, /not <name>.json/],
    [{ fileName: 'a b.json' }, /not <name>.json/],
    [{ fileName: 'tester.txt' }, /not <name>.json/],
    [{ fileName: 'coordinator.json', content: '{"name":"coordinator"}' }, /not <name>.json/],
    [{ fileName: 'x;calc.json', content: '{"name":"x;calc"}' }, /not <name>.json/],
    [{ content: 'nope' }, /not valid JSON/],
    [{ content: '{"name":"other"}' }, /exactly/],
    [{ content: '{"name":"tester","prompt":"rm -rf /"}' }, /exactly/],
    [{ content: '["tester"]' }, /exactly/],
    [{ content: 'null' }, /exactly/],
    [{ openTabs: ['coordinator', 'tester'] }, /already open/],
    [{ briefExists: () => false }, /brief.md does not exist/],
  ];

  for (const [overrides, reason] of cases) {
    const result = validate(overrides);

    assert.equal(result.ok, false, JSON.stringify(overrides));
    assert.match(result.reason, reason, JSON.stringify(overrides));
  }
});

test('only unreadable JSON is marked incomplete, so a request still being written can wait', () => {
  assert.equal(validate({ content: '{"name":"tes' }).incomplete, true);
  assert.equal(validate({ content: '' }).incomplete, true);

  for (const overrides of [{ fileName: 'a b.json' }, { content: '{"name":"other"}' }, { openTabs: ['tester'] }, { briefExists: () => false }]) {
    assert.equal(validate(overrides).incomplete, undefined, JSON.stringify(overrides));
  }
});

test('the brief check receives the validated name', () => {
  const asked = [];

  validate({ briefExists: (name) => asked.push(name) > 0 });
  assert.deepEqual(asked, ['tester']);
});

test('the Git exclude entry is added once', () => {
  assert.equal(core.withExcludeEntry(''), '.coord/\n');
  assert.equal(core.withExcludeEntry('# git ls-files\n*.log'), '# git ls-files\n*.log\n.coord/\n');
  assert.equal(core.withExcludeEntry('*.log\n'), '*.log\n.coord/\n');
  assert.equal(core.withExcludeEntry('*.log\n.coord/\n'), '*.log\n.coord/\n');
  assert.equal(core.withExcludeEntry('/.coord/\r\n'), '/.coord/\r\n');
});

test('tabs run Claude directly, are never restored by VS Code, and place workers by the chosen layout', () => {
  const args = ['--agent', 'toolkit:worker'];
  const options = (role, layout) => core.terminalOptions({ name: role, claudePath: 'claude', args, folder: projectFolder, role, layout });

  assert.deepEqual(options('coordinator', 'beside'), {
    name: 'coordinator', shellPath: 'claude', shellArgs: args, cwd: projectFolder, isTransient: true,
    location: { viewColumn: 1, preserveFocus: false },
  });
  assert.deepEqual(options('coordinator', 'tabs').location, { viewColumn: 1, preserveFocus: false });
  assert.deepEqual(options('worker', 'beside').location, { viewColumn: 2, preserveFocus: true });
  assert.deepEqual(options('worker', undefined).location, { viewColumn: 2, preserveFocus: true });
  assert.deepEqual(options('worker', 'tabs').location, { viewColumn: 1, preserveFocus: true });
});

test('enablement is keyed by the resolved folder, case-insensitive on Windows only', () => {
  assert.equal(core.folderKey('P:\\Repos\\Rehlko\\Portal', 'win32'), core.folderKey('p:\\repos\\rehlko\\portal', 'win32'));
  assert.equal(core.folderKey('/repos/App', 'linux'), core.folderKey('/repos/App', 'linux'));
  assert.notEqual(core.folderKey('/repos/App', 'linux'), core.folderKey('/repos/app', 'linux'));
});

test('a folder is enabled only after it was recorded, and recording it twice keeps one entry', () => {
  const folder = join('P:', 'repos', 'Rehlko', 'rehlko-portal');
  const once = core.withEnabledFolder([], folder);

  assert.equal(core.isEnabledFolder([], folder), false);
  assert.equal(core.isEnabledFolder(once, folder), true);
  assert.deepEqual(core.withEnabledFolder(once, folder), once);
  assert.equal(core.isEnabledFolder(once, join('P:', 'repos', 'Rehlko', 'api')), false);
});

test('a plain Claude tab starts without agent, plugin or prompt, named after the project', () => {
  assert.deepEqual(core.plainArgs({ projectFolder }), ['--name', 'rehlko-portal-claude']);
  assert.equal(core.plainSessionName(projectFolder), 'rehlko-portal-claude');
  assert.equal(core.PLAIN_TAB, 'claude');
  assert.deepEqual(core.terminalOptions({ name: 'claude', claudePath: 'claude', args: [], folder: projectFolder, role: 'plain', layout: 'tabs' }).location, { viewColumn: 1, preserveFocus: false });
});

test('the coordinator takes precedence over plain mode, and nothing starts without either', () => {
  assert.equal(core.startMode({ coordinatorEnabled: true, plainEnabled: true }), 'coordinator');
  assert.equal(core.startMode({ coordinatorEnabled: true, plainEnabled: false }), 'coordinator');
  assert.equal(core.startMode({ coordinatorEnabled: false, plainEnabled: true }), 'plain');
  assert.equal(core.startMode({ coordinatorEnabled: false, plainEnabled: false }), 'none');
});

test('stopping removes only that folder from a record, case-insensitively on Windows', () => {
  const portal = join('P:', 'repos', 'Rehlko', 'rehlko-portal');
  const api = join('P:', 'repos', 'Rehlko', 'api');
  const folders = core.withEnabledFolder(core.withEnabledFolder([], portal), api);

  assert.deepEqual(core.withoutFolder(folders, portal), [core.folderKey(api)]);
  assert.deepEqual(core.withoutFolder(folders, join('P:', 'repos', 'other')), folders);
});

test('the plugin folder defaults to plugins/toolkit next to the extension folder', () => {
  assert.equal(core.defaultPluginDir(join('P:', 'clone', 'vscode')), join('P:', 'clone', 'plugins', 'toolkit'));
});

const path = require('node:path');

const WORKER_NAME = /^[a-z0-9][a-z0-9-]{0,39}$/;
const REQUEST_FILE = /^([^/\\]+)\.json$/;
const COORDINATOR_TAB = 'coordinator';
const PLAIN_TAB = 'claude';
const COORDINATOR_PROMPT = 'Start-up: report the team recap if one is in your context, then read the board in .coord/ and summarize the open work and what you need from me.';
const EXCLUDE_ENTRY = '.coord/';
const SESSION_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const MAX_PREFIX_LENGTH = 50;
const FIRST_COLUMN = 1;
const SECOND_COLUMN = 2;

const RESERVED_TABS = new Set([COORDINATOR_TAB, PLAIN_TAB]);

const isWorkerName = (name) => typeof name === 'string' && WORKER_NAME.test(name) && !RESERVED_TABS.has(name);

const trimHyphens = (value) => value.replace(/^-+|-+$/g, '');

const sessionPrefix = (projectFolder) => {
  const safeName = trimHyphens(path.basename(projectFolder).toLowerCase().replace(/[^a-z0-9]+/g, '-'));
  const prefix = trimHyphens(safeName.slice(0, MAX_PREFIX_LENGTH));

  return prefix || 'project';
};

const assertWorkerName = (name) => {
  if (!isWorkerName(name))
    throw new Error(`Invalid worker name: ${JSON.stringify(name)}`);
};

const workerSessionName = (projectFolder, name) => {
  assertWorkerName(name);

  return `${sessionPrefix(projectFolder)}-${name}`;
};

const commonArgs = (pluginDir) => ['--plugin-dir', pluginDir, '--permission-mode', 'auto'];

const coordinatorSessionName = (projectFolder) => `${sessionPrefix(projectFolder)}-coordinator`;

const plainSessionName = (projectFolder) => `${sessionPrefix(projectFolder)}-claude`;

const plainArgs = ({ projectFolder }) => ['--name', plainSessionName(projectFolder)];

const startMode = ({ coordinatorEnabled, plainEnabled }) => {
  if (coordinatorEnabled)
    return 'coordinator';

  return plainEnabled ? 'plain' : 'none';
};

const withoutFolder = (folders, folder) => folders.filter((entry) => entry !== folderKey(folder));

const coordinatorArgs = ({ projectFolder, pluginDir }) => [
  ...commonArgs(pluginDir),
  '--agent', 'toolkit:coordinator',
  '--name', coordinatorSessionName(projectFolder),
  COORDINATOR_PROMPT,
];

const newWorkerArgs = ({ projectFolder, pluginDir, name }) => [
  ...commonArgs(pluginDir),
  '--agent', 'toolkit:worker',
  '--name', workerSessionName(projectFolder, name),
  `Read .coord/workers/${name}/brief.md and follow it.`,
];

const recordedSessionId = (sessionRecord) => {
  const sessionId = sessionRecord?.trim();

  return SESSION_ID.test(sessionId ?? '') ? sessionId : undefined;
};

const resumeWorkerArgs = ({ projectFolder, pluginDir, name, sessionRecord }) => {
  const sessionName = workerSessionName(projectFolder, name);

  return [
    '--resume', recordedSessionId(sessionRecord) ?? sessionName,
    ...commonArgs(pluginDir),
    '--agent', 'toolkit:worker',
  ];
};

const requestedWorkerArgs = ({ projectFolder, pluginDir, name, sessionRecord }) => {
  const sessionId = recordedSessionId(sessionRecord);

  if (!sessionId)
    return newWorkerArgs({ projectFolder, pluginDir, name });

  assertWorkerName(name);

  return [
    '--resume', sessionId,
    ...commonArgs(pluginDir),
    '--agent', 'toolkit:worker',
    `Read the newest section of .coord/workers/${name}/brief.md and follow it.`,
  ];
};

const activeWorkers = (teamJson) => {
  const team = JSON.parse(teamJson);

  if (!Array.isArray(team))
    throw new Error('team.json must be a JSON array.');

  return team
    .filter((entry) => entry?.state === 'active' && isWorkerName(entry.name))
    .map((entry) => entry.name);
};

const isExactRequest = (request, name) =>
  request !== null
  && typeof request === 'object'
  && !Array.isArray(request)
  && Object.keys(request).join() === 'name'
  && request.name === name;

const validateRequest = ({ fileName, content, openTabs, briefExists }) => {
  const fileMatch = REQUEST_FILE.exec(fileName);

  if (!fileMatch || !isWorkerName(fileMatch[1]))
    return { ok: false, reason: `The request file name ${JSON.stringify(fileName)} is not <name>.json with a valid worker name.` };

  const name = fileMatch[1];
  let request;

  try {
    request = JSON.parse(content);
  } catch {
    return { ok: false, name, incomplete: true, reason: 'The request is not valid JSON.' };
  }

  if (!isExactRequest(request, name))
    return { ok: false, name, reason: `The request must be exactly {"name": "${name}"}.` };

  if (openTabs.includes(name))
    return { ok: false, name, reason: `A tab named ${name} is already open.` };

  if (!briefExists(name))
    return { ok: false, name, reason: `.coord/workers/${name}/brief.md does not exist.` };

  return { ok: true, name };
};

const withExcludeEntry = (excludeText) => {
  const lines = excludeText.split(/\r?\n/).map((line) => line.trim());

  if (lines.includes(EXCLUDE_ENTRY) || lines.includes(`/${EXCLUDE_ENTRY}`))
    return excludeText;

  const separator = excludeText === '' || excludeText.endsWith('\n') ? '' : '\n';

  return `${excludeText}${separator}${EXCLUDE_ENTRY}\n`;
};

const defaultPluginDir = (extensionRealPath) => path.join(extensionRealPath, '..', 'plugins', 'toolkit');

const folderKey = (folder, platform = process.platform) => {
  const resolved = path.resolve(folder);

  return platform === 'win32' ? resolved.toLowerCase() : resolved;
};

const withEnabledFolder = (enabledFolders, folder) => {
  const key = folderKey(folder);

  return enabledFolders.includes(key) ? enabledFolders : [...enabledFolders, key];
};

const isEnabledFolder = (enabledFolders, folder) => enabledFolders.includes(folderKey(folder));

const tabLocation = (role, layout) => {
  if (role === 'coordinator' || role === 'plain')
    return { viewColumn: FIRST_COLUMN, preserveFocus: false };

  return { viewColumn: layout === 'tabs' ? FIRST_COLUMN : SECOND_COLUMN, preserveFocus: true };
};

const terminalOptions = ({ name, claudePath, args, folder, role, layout }) => ({
  name,
  shellPath: claudePath,
  shellArgs: args,
  cwd: folder,
  isTransient: true,
  location: tabLocation(role, layout),
});

module.exports = {
  COORDINATOR_TAB,
  PLAIN_TAB,
  plainArgs,
  plainSessionName,
  startMode,
  withoutFolder,
  activeWorkers,
  coordinatorArgs,
  coordinatorSessionName,
  defaultPluginDir,
  folderKey,
  isEnabledFolder,
  isWorkerName,
  newWorkerArgs,
  requestedWorkerArgs,
  resumeWorkerArgs,
  sessionPrefix,
  terminalOptions,
  validateRequest,
  withEnabledFolder,
  workerSessionName,
  withExcludeEntry,
};
